  const pressureModifier = Math.max(0.2, 1 - pop.populationPressure * 0.5);

  pop.adjustedBirthRate = pop.baselineBirthRate *
    meaningModifier *
    economicModifier *
    healthcareModifier *
    stabilityModifier *
