 */
export type ScenarioType = 
  | 'grey_goo'
  | 'mirror_life'
  | 'embodied_takeover'
  | 'digital_takeover'
  | 'induced_war'
  | 'slow_displacement'
  | 'physics_catastrophe'
  | 'bioweapon_pandemic';

