    // Population impact: State collapse causes chaos, riots, food distribution failures (0.1-0.3% casualties)
    const { addAcuteCrisisDeaths } = require('./populationDynamics');
    const currentPop = state.humanPopulationSystem.population;
    const collapseDeaths = currentPop * 0.002; // 0.2% immediate casualties from civil chaos
    addAcuteCrisisDeaths(state, collapseDeaths, 'Institutional failure - state collapse chaos');

    // High risk of dystopia transition
