    reproductiveCrisisActive: false,
    chronicDiseaseEpidemicActive: false,
    bioaccumulationCollapseActive: false,
    exposureMonths: 0,
    greenChemistryDeployment: 0.05,      // Minimal adoption
    circularEconomyDeployment: 0.10,     // Some programs
