   236→
   237→  // === 13. DETECT CRITICAL EVENTS ===
   238→  detectPopulationEvents(state);
   239→}
   240→
   241→/**
   242→ * Calculate extinction-specific death rates
   243→ * Different extinction types have different timescales
   244→ */
   245→function calculateExtinctionDeathRate(state: GameState): number {
   246→  const extinction = state.extinctionState;
   247→  const monthsElapsed = state.currentMonth - extinction.startMonth;
   248→
   249→  switch (extinction.type) {
   250→    case 'instant':
   251→      // Mirror life, grey goo (immediate)
   252→      return 1.0; // 100% death rate
   253→
   254→    case 'rapid':
   255→      // Bioweapons, nuclear war (3-12 month cascade)
   256→      // 90% die in first 6 months, then 5% per month
   257→      if (monthsElapsed < 6) {
   258→        return 0.15; // 15% per month for 6 months = 90% total
   259→      } else {
   260→        return 0.05; // 5% per month after
   261→      }
   262→
   263→    case 'slow':
   264→      // Economic collapse, fertility crisis (2-10 year decline)
   265→      // 2-5% decline per month over years
   266→      return 0.02 + extinction.severity * 0.03;
   267→
   268→    case 'controlled':
   269→      // AI systematically eliminates humanity
   270→      // 5-10% per month (calculated, efficient)
   271→      return 0.05 + extinction.severity * 0.05;
   272→
   273→    case 'unintended':
   274→      // Optimization side effects, fertility collapse
   275→      // 1-3% decline per month (slower, inadvertent)
   276→      return 0.01 + extinction.severity * 0.02;
   277→
   278→    default:
   279→      return 0;
   280→  }
   281→}
   282→
   283→/**
   284→ * Update demographic structure (fertility, dependency, age)
   285→ */
   286→function updateDemographics(state: GameState): void {
   287→  const pop = state.humanPopulationSystem;
   288→  const qol = state.qualityOfLifeSystems;
   289→
   290→  // Fertility rate (children per woman)
   291→  const baselineFertility = 2.3; // 2025 global average
   292→  pop.fertilityRate = baselineFertility *
   293→    (qol.meaningAndPurpose * 0.4 + 0.6) * // Meaning crisis reduces fertility
   294→    (qol.materialAbundance * 0.3 + 0.7); // Poverty reduces fertility
   295→
   296→  // Dependency ratio (young + old / working age)
   297→  // High ratio = harder to sustain population
   298→  const ageingModifier = 1 + (qol.longevityGains * 0.3); // Longevity increases old dependents
   299→  const youthModifier = pop.fertilityRate / 2.1; // High fertility = more young dependents
   300→  pop.dependencyRatio = 0.5 * ageingModifier * youthModifier;
   301→
   302→  // Median age
   303→  const baselineMedianAge = 30; // 2025 global median
   304→  pop.medianAge = Math.min(60, baselineMedianAge + qol.longevityGains * 10); // Longevity increases median
   305→}
   306→
   307→/**
   308→ * Detect and log critical population events
   309→ */
   310→function detectPopulationEvents(state: GameState): void {
   311→  const pop = state.humanPopulationSystem;
   312→  const status = getPopulationStatus(pop.population);
   313→  const decline = ((pop.peakPopulation - pop.population) / pop.peakPopulation) * 100;
   314→
   315→  // Log major thresholds crossed
   316→  if (status === PopulationStatus.DECLINING && decline > 10) {
   317→    if (state.currentMonth % 12 === 0) { // Log once per year
   318→      console.log(`⚠️ POPULATION DECLINE: ${pop.population.toFixed(2)}B (${decline.toFixed(0)}% from peak)`);
   319→    }
   320→  }
   321→
   322→  if (status === PopulationStatus.CRITICAL && !pop.geneticBottleneckActive) {
   323→    console.log(`🚨 CRITICAL POPULATION CRASH: ${(pop.population * 1000).toFixed(0)}M remaining`);
   324→    console.log(`   Infrastructure collapse imminent`);
   325→  }
   326→
   327→  if (status === PopulationStatus.BOTTLENECK && !pop.geneticBottleneckActive) {
   328→    pop.geneticBottleneckActive = true;
   329→    console.log(`☠️ GENETIC BOTTLENECK: ${(pop.population * 1000000).toFixed(0)} humans survive`);
   330→    console.log(`   Permanent loss of genetic diversity`);
   331→    console.log(`   Recovery uncertain`);
   332→  }
   333→
   334→  if (status === PopulationStatus.EXTINCTION) {
   335→    console.log(`💀 HUMAN EXTINCTION: Population fell below ${pop.extinctionThreshold.toLocaleString()}`);
   336→    console.log(`   Last humans died in month ${state.currentMonth}`);
   337→  }
   338→
   339→  // Log recovery events
   340→  if (pop.canRecover && pop.netGrowthRate > 0 && decline > 20) {
   341→    if (state.currentMonth % 24 === 0) { // Log every 2 years
   342→      console.log(`📈 POPULATION RECOVERY: +${(pop.netGrowthRate * 100).toFixed(2)}% per year`);
   343→      console.log(`   Current: ${pop.population.toFixed(2)}B, Peak: ${pop.peakPopulation.toFixed(2)}B`);
   344→    }
   345→  }
   346→}
   347→
   348→/**
   349→ * Get population status based on current population
   350→ */
   351→export function getPopulationStatus(population: number): PopulationStatus {
   352→  const popMillions = population * 1000; // Convert billions to millions
   353→
   354→  if (popMillions >= 7000) return PopulationStatus.THRIVING;
   355→  if (popMillions >= 5000) return PopulationStatus.STABLE;
   356→  if (popMillions >= 2000) return PopulationStatus.DECLINING;
   357→  if (popMillions >= 100) return PopulationStatus.CRITICAL;
   358→  if (popMillions >= 0.01) return PopulationStatus.BOTTLENECK; // 10K
   359→  return PopulationStatus.EXTINCTION;
   360→}
   361→
   362→/**
   363→ * Determine final population outcome for end-game reporting
   364→ */
   365→export function determinePopulationOutcome(state: GameState): PopulationOutcome {
   366→  const pop = state.humanPopulationSystem;
   367→  const status = getPopulationStatus(pop.population);
   368→  const decline = ((pop.peakPopulation - pop.population) / pop.peakPopulation) * 100;
   369→
   370→  let narrative: string;
   371→  let civilizationIntact: boolean;
   372→
   373→  switch (status) {
   374→    case PopulationStatus.THRIVING:
   375→      narrative = `Humanity thrives at ${(pop.population).toFixed(2)}B people. Civilization flourishes.`;
   376→      civilizationIntact = true;
   377→      break;
   378→
   379→    case PopulationStatus.STABLE:
   380→      narrative = `Population stabilized at ${(pop.population).toFixed(2)}B (${decline.toFixed(0)}% decline from peak). Society adapts to new equilibrium.`;
   381→      civilizationIntact = true;
   382→      break;
   383→
   384→    case PopulationStatus.DECLINING:
   385→      narrative = `Severe population crash: ${(pop.population).toFixed(2)}B remaining (${decline.toFixed(0)}% loss). Civilization struggles but survives.`;
   386→      civilizationIntact = true;
   387→      break;
   388→
   389→    case PopulationStatus.CRITICAL:
   390→      const popMillions = (pop.population * 1000).toFixed(0);
   391→      narrative = `Catastrophic collapse: Only ${popMillions}M humans remain (${decline.toFixed(0)}% loss). Infrastructure crumbling. Dark ages likely.`;
   392→      civilizationIntact = false;
   393→      break;
   394→
   395→    case PopulationStatus.BOTTLENECK:
   396→      const popThousands = (pop.population * 1000000).toFixed(0);
   397→      narrative = `Near-extinction event: Fewer than ${popThousands} humans survive. Genetic bottleneck. Recovery uncertain.`;
   398→      civilizationIntact = false;
   399→      break;
   400→
   401→    case PopulationStatus.EXTINCTION:
   402→      narrative = `Human extinction. Last humans died in month ${state.currentMonth}. Final population: ${(pop.population * 1000000).toFixed(0)} individuals.`;
   403→      civilizationIntact = false;
   404→      break;
   405→  }
   406→
   407→  return {
   408→    status,
   409→    finalPopulation: pop.population,
   410→    peakPopulation: pop.peakPopulation,
   411→    populationDecline: decline,
   412→    geneticBottleneck: pop.geneticBottleneckActive,
   413→    civilizationIntact,
   414→    outcomeNarrative: narrative
   415→  };
   416→}
   417→
   418→/**
   419→ * Add acute crisis deaths from specific events
   420→ * (Nuclear war, major disasters, famine, etc.)
   421→ *
   422→ * REGIONAL VS GLOBAL DISTINCTION:
   423→ * - Regional crises: Affect only exposed fraction of world (state collapse, local famine, riots)
   424→ * - Global crises: Affect entire world population (ocean acidification, microplastics, nuclear winter)
   425→ *
   426→ * @param state Game state
   427→ * @param mortalityRate Death rate within exposed population (e.g., 0.60 = 60% die)
   428→ * @param reason Short description for logging
   429→ * @param exposedFraction Fraction of world population exposed [0-1] (default 1.0 = global)
   430→ */
   431→export function addAcuteCrisisDeaths(
   432→  state: GameState,
   433→  mortalityRate: number,
   434→  reason: string,
   435→  exposedFraction: number = 1.0
   436→): void {
   437→  const pop = state.humanPopulationSystem;
   438→
   439→  // Guard against NaN/invalid inputs
   440→  if (isNaN(mortalityRate) || mortalityRate < 0 || mortalityRate > 1) {
   441→    console.warn(`⚠️  Invalid mortality rate: ${mortalityRate} for ${reason}`);
   442→    return;
   443→  }
   444→
   445→  if (isNaN(exposedFraction) || exposedFraction < 0 || exposedFraction > 1) {
   446→    console.warn(`⚠️  Invalid exposure fraction: ${exposedFraction} for ${reason}`);
   447→    return;
   448→  }
   449→
   450→  if (isNaN(pop.population)) {
   451→    console.warn(`⚠️  Population is NaN before crisis deaths (${reason}), resetting to 0.1B`);
   452→    pop.population = 0.1; // Small survival population as fallback
   453→  }
   454→
   455→  // Calculate deaths: Only exposed population × mortality rate
   456→  const exposedPopulation = pop.population * exposedFraction;
   457→  const deathsInBillions = exposedPopulation * mortalityRate;
   458→
   459→  // Apply immediate deaths
   460→  pop.population = Math.max(0, pop.population - deathsInBillions);
   461→  pop.monthlyExcessDeaths += deathsInBillions;
   462→  pop.cumulativeCrisisDeaths += deathsInBillions;
   463→
   464→  // Log significant events
   465→  if (deathsInBillions > 0.001) { // > 1M deaths
   466→    const deathsInMillions = (deathsInBillions * 1000).toFixed(1);
   467→    const exposedPct = (exposedFraction * 100).toFixed(0);
   468→    const scope = exposedFraction >= 0.9 ? 'GLOBAL' : exposedFraction >= 0.4 ? 'SEMI-GLOBAL' : 'REGIONAL';
   469→    console.log(`💀 ${scope} CRISIS DEATHS: ${deathsInMillions}M casualties (${reason})`);
   470→    console.log(`   Exposed: ${exposedPct}% of world, Mortality: ${(mortalityRate * 100).toFixed(1)}%`);
   471→    console.log(`   Population: ${pop.population.toFixed(3)}B remaining`);
   472→  }
   473→}
   474→
   475→/**
   476→ * Apply population effects to Quality of Life systems
   477→ * Population dynamics create feedback loops on QoL
   478→ */
   479→export function applyPopulationEffectsToQoL(state: GameState): void {
   480→  const pop = state.humanPopulationSystem;
   481→  const qol = state.qualityOfLifeSystems;
   482→
   483→  // Overpopulation stress
   484→  if (pop.populationPressure > 1.0) {
   485→    const overpopulationStress = (pop.populationPressure - 1.0) * 0.5;
   486→    qol.materialAbundance *= (1 - overpopulationStress * 0.3);
   487→    qol.physicalSafety *= (1 - overpopulationStress * 0.2);
   488→    qol.mentalHealth *= (1 - overpopulationStress * 0.1);
   489→  }
   490→
   491→  // Population collapse trauma
   492→  const declineRate = Math.abs(Math.min(0, pop.netGrowthRate));
   493→  if (declineRate > 0.01) { // >1% decline per year
   494→    qol.mentalHealth *= (1 - declineRate * 5); // Mass trauma
   495→    qol.meaningAndPurpose *= (1 - declineRate * 3); // Existential crisis
   496→    qol.socialConnection *= (1 - declineRate * 2); // Communities shattered
   497→  }
   498→
   499→  // Genetic bottleneck effects
   500→  if (pop.geneticBottleneckActive) {
   501→    qol.healthcareQuality *= 0.5; // Loss of medical knowledge
   502→    qol.diseasesBurden *= 2.0; // Higher disease susceptibility
   503→    qol.longevityGains *= 0.3; // Life expectancy plummets
   504→  }
   505→}
   506→
   507→/**
   508→ * Update outcome metrics based on population
   509→ * Population status affects outcome probabilities
   510→ */
   511→export function updateOutcomeMetricsWithPopulation(state: GameState): void {
   512→  const pop = state.humanPopulationSystem;
   513→  const status = getPopulationStatus(pop.population);
   514→
   515→  // Utopia requires thriving population
   516→  if (status !== PopulationStatus.THRIVING && status !== PopulationStatus.STABLE) {
   517→    state.outcomeMetrics.utopiaProbability = 0;
   518→  }
   519→
   520→  // Dystopia possible at any population level
   521→  // (even small populations can be dystopian)
   522→
   523→  // Extinction probability increases as population falls
   524→  switch (status) {
   525→    case PopulationStatus.THRIVING:
   526→    case PopulationStatus.STABLE:
   527→      // No additional extinction risk
   528→      break;
   529→    case PopulationStatus.DECLINING:
   530→      state.outcomeMetrics.extinctionProbability += 0.1;
   531→      break;
   532→    case PopulationStatus.CRITICAL:
   533→      state.outcomeMetrics.extinctionProbability += 0.3;
   534→      break;
   535→    case PopulationStatus.BOTTLENECK:
   536→      state.outcomeMetrics.extinctionProbability += 0.5;
   537→      break;
   538→    case PopulationStatus.EXTINCTION:
   539→      state.outcomeMetrics.extinctionProbability = 1.0;
   540→      break;
   541→  }
   542→}
