   750→  const extinctionState = { ...state.extinctionState };
   751→  const events: GameEvent[] = [];
   752→  
   753→  switch (extinctionState.type) {
   754→    case 'instant':
   755→      // Instant = already complete
   756→      return { newExtinctionState: extinctionState, events: [], isComplete: true };
   757→      
   758→    case 'rapid':
   759→      return progressRapidExtinction(state, extinctionState, monthsElapsed, events, random);
   760→      
   761→    case 'slow':
   762→      return progressSlowExtinction(state, extinctionState, monthsElapsed, events, random);
   763→      
   764→    case 'controlled':
   765→      return progressControlledExtinction(state, extinctionState, monthsElapsed, events, random);
   766→      
   767→    case 'unintended':
   768→      return progressUnintendedExtinction(state, extinctionState, monthsElapsed, events, random);
   769→      
   770→    default:
   771→      return { newExtinctionState: extinctionState, events: [], isComplete: false };
   772→  }
