  const isWithinRange = exposure1.cancerRisk.radiationBonus >= 0.09 && exposure1.cancerRisk.radiationBonus <= 0.31;
  if (!isWithinRange) {
    throw new Error(`Expected 0.10-0.30, got ${exposure1.cancerRisk.radiationBonus}`);
  }
});

