    preIndustrialValue: 0.0,
    highRiskThreshold: 1.5,
    status: 'high_risk',
    trend: 'worsening',
    breachYear: 1950,
    monthsBreached: (2025 - 1950) * 12,
    isCoreBoundary: true,
    interactionStrength: 1.0,              // Affects everything
