   433→/**
   434→ * Calculate energy constraints on AI growth (NEW - Oct 12, 2025)
   435→ *
   436→ * Determines if data center power consumption is approaching limits,
   437→ * and calculates constraint severity to slow AI capability growth.
   438→ *
   439→ * Key Thresholds:
   440→ * - <5% of global power: No constraint
   441→ * - 5-10% of global power: Warning zone (soft constraint)
   442→ * - >10% of global power: Hard constraint (severe slowdown)
   443→ */
   444→function calculateEnergyConstraints(power: PowerGenerationSystem): void {
   445→  // Calculate utilization rate (what % of global power is data centers using?)
   446→  const utilizationRate = power.dataCenterPower / power.totalElectricityGeneration;
   447→
   448→  // Soft constraint threshold (warning zone)
   449→  const softThreshold = 0.05; // 5% of global power
   450→  const hardThreshold = power.maxDataCenterPowerFraction; // 10% by default
   451→
   452→  // Calculate constraint severity [0, 1]
   453→  if (utilizationRate < softThreshold) {
   454→    // No constraint - plenty of power available
