        console.log(`Utilization: ${(utilizationRate * 100).toFixed(1)}%`);
        console.log(`Energy Constraint Active: ${power.energyConstraintActive ? 'YES' : 'NO'}`);

        if (power.energyConstraintActive) {
          console.log(`Constraint Severity: ${(power.constraintSeverity * 100).toFixed(0)}%`);
          console.log(`AI Growth Multiplier: ${((1 - power.constraintSeverity) * 100).toFixed(0)}%`);
          console.log(`⚠️ AI research is being slowed by energy scarcity!`);
        }

        // Check AI capability growth
        const avgCapability = state.aiAgents
          .filter(ai => ai.lifecycleState !== 'retired')
          .reduce((sum, ai) => {
            const total = ai.capabilityProfile.cognitive +
                         ai.capabilityProfile.selfImprovement +
                         ai.capabilityProfile.digital;
            return sum + total;
          }, 0) / Math.max(1, state.aiAgents.filter(ai => ai.lifecycleState !== 'retired').length);

        console.log(`Average AI Capability (3 core dims): ${avgCapability.toFixed(2)}`);
      }
    }

    // Final summary
    console.log('\n=== FINAL STATE (5 years) ===');
    console.log(getPowerGenerationSummary(state));

    const power = state.powerGenerationSystem;
    const utilizationRate = power.dataCenterPower / power.totalElectricityGeneration;

    console.log('\n=== TEST RESULTS ===');
    console.log(`✅ Simulation completed successfully`);
    console.log(`Final utilization: ${(utilizationRate * 100).toFixed(1)}%`);
    console.log(`Constraint activated: ${power.energyConstraintActive ? 'YES' : 'NO'}`);

    if (utilizationRate > 0.20) {
      console.log(`✅ PASS: Hit soft threshold (20%)`);
    }

    if (power.energyConstraintActive) {
      console.log(`✅ PASS: Energy constraints activated as expected`);
    } else {
      console.log(`⚠️ INFO: Energy constraints not activated yet (still below 20%)`);
    }

  } else {
    console.error('❌ FAIL: Power generation system not initialized');
    process.exit(1);
  }
}

testEnergyConstraints().catch(err => {
  console.error('❌ Test failed:', err);
  process.exit(1);
});

