 * - Major economies (Japan, Germany, Brazil, Indonesia)
 * - AI hubs (US, UK, Canada, China)
 * - Strategic nations (Nigeria, Bangladesh)
 * - Hegemons (US, China, Russia, India, UK)
 */

export type CountryName =
  | 'United States'
