    militaryRnDPercent: 6,
  });

  // PAKISTAN - Nuclear Regional Power
  // SIPRI 2024: $10.4B (likely underreported)
  // No overseas bases
  // Estimated emissions: ~2M tons/year
  militaryData.set('Pakistan', {
