    breakthroughTech: new Map([
      ['solar_power', {
        unlocked: true,
        unlockedAt: 0,
        researchPoints: 100,
        diffusion: {
          developed: 0.8,
          developing: 0.3,
          diffusionRate: 0.05
        }
