  const richCountries = ['United States', 'Germany', 'Japan'] as CountryName[];
  const anySharing = richCountries.some(
    name => countries[name].greenTechShared! > 0
  );
  assert(
    anySharing,
    'Rich countries (US, Germany, Japan) share green technology'
  );

